def route(points):
    o=[r[:] for r in test]
    gate_rows={8,11,14,20}
    for (r1,c1),(r2,c2) in zip(points,points[1:]):
        # Generic vertical-first path, horizontal on the row before a downward gate
        # (or after an upward gate).
        if r2>r1:
            start=r1+1 if r1 in gate_rows else r1; end=r2-1 if r2 in gate_rows else r2
        else:
            start=r1-1 if r1 in gate_rows else r1; end=r2+1 if r2 in gate_rows else r2
        for r in range(min(start,end),max(start,end)+1): o[r][c1]=5
        for c in range(min(c1,c2),max(c1,c2)+1): o[end][c]=5
        if r2 in gate_rows:o[r2][c2]=5
    return o
